VALUES ('business-mes-ai', 'ko-KR', $seed${"shell":{"kicker":"MES AI","kickerSub":"제조AI(M.AX)","headLead":"문서를 읽고, 규정을 대조하고, ","headStrong":"묻는 말에 답합니다","desc":"사람이 옮겨 적던 자리를 AI 가 대신합니다. 문서에서 값을 뽑아 MES 와 맞춰 보고, 국가별 규제를 대조하고, 흩어진 제조 지식을 대화로 꺼냅니다.","ctaTitle":"","ctaDesc":""},"lead":{"title":"읽고, 대조하고, 물어봅니다","desc":"","heroN":"3가지","heroLabel":"MES 안에서 도는 AI — 읽기·대조하기·물어보기","items":[{"t":"자재 입출고 AI 자동화","d":"거래명세서·성적서를 OCR 로 읽어 MES 에 자동 입고합니다."},{"t":"규제 자동 대조","d":"국가별 규제를 자동 대조해 검증합니다."},{"t":"제조 지식 대화","d":"쌓인 제조 지식을 대화로 꺼내 씁니다."}]},"heroShots":[{"image":{"id":null,"alt":"AI 가 양식 구조를 읽고 MES 필드에 맞추는 화면","src":"/screens/form-mapping.jpg","width":1600,"height":799},"tag":"양식 자동 매핑","url":"max.drvalue.co.kr / 양식"},{"image":{"id":null,"alt":"양식 업로드 화면 — 데이터베이스 연결 상태와 분석된 hwp·hwpx 양식 목록","src":"/screens/solution-form-automation-upload.jpg","width":1600,"height":1121},"tag":"양식 업로드","url":"max.drvalue.co.kr / 양식 업로드"},{"image":{"id":null,"alt":"문서 생성 화면 — 레코드를 고르면 품질관리기록서 양식을 값으로 채운다","src":"/screens/solution-form-automation-generate.jpg","width":1600,"height":1024},"tag":"문서 생성","url":"max.drvalue.co.kr / 문서 생성"}],"bento":{"kicker":"실제 화면","title":"MES 안에서 도는 AI 셋","desc":"문서에서 값을 뽑아 MES 와 맞춰 보고, 국가별 규제를 대조하고, 흩어진 제조 지식을 대화로 꺼냅니다."},"ais":[{"label":"자재 입출고 AI 자동화","title":"자재 입출고 **AI 자동화**","desc":"거래명세서·성적서를 OCR 로 읽어 MES 에 자동 입고합니다.","steps":[{"text":"자재 도착, 거래명세서·성적서를 모바일 단말기로 촬영·업로드"},{"text":"OCR 엔진이 문서 구조를 자동 인식해 **품목명·수량·단가·LOT번호** 추출"},{"text":"추출값과 MES 원료 마스터 데이터 자동 대조·검증"},{"text":"검증 완료 시 **MES에 자동 입고**, 불일치 건만 담당자 확인"},{"text":"생산 투입 시 제조 BOM에 따라 자재 자동 출고 처리"},{"text":"입출고 연동으로 재고 실시간 갱신, 부족 시 사전 알림"}],"shot":{"id":null,"alt":"원료 입출고 화면 — 원료코드·재고수량·입고일·보증기한·최근이력","src":"/screens/cos-material.jpg","width":1600,"height":463},"url":"max.drvalue.co.kr / 자재 입출고","tone":""},{"label":"글로벌 규제 자동검증 AI","title":"글로벌 규제 **자동검증** AI","desc":"국가별 규제를 자동 대조해 검증합니다.","steps":[{"text":"각국 규제 정보를 자동 크롤링"},{"text":"레시피 성분을 **국가별 규제 기준으로 AI 검증**"},{"text":"규제 변경 이력 알림"},{"text":"규제 저촉 시 **대체 원료 제안**"}],"shot":{"id":null,"alt":"국가별 규제 기준으로 성분을 검증하는 화면","src":"/screens/cos-regulation.jpg","width":1600,"height":836},"url":"max.drvalue.co.kr / 규제 검증","tone":"sand"},{"label":"제조지식 대화형 AI 비서","title":"제조지식 **대화형 AI 비서**","desc":"쌓인 제조 지식을 대화로 꺼내 씁니다.","steps":[{"text":"유사 레시피 검색·비교"},{"text":"원료 대체 이력 추적"},{"text":"클레임 원인 추적·사례 검색"},{"text":"MES 실시간 데이터 조회"},{"text":"**직급별 권한 분리**로 안전한 지식 접근"}],"shot":{"id":null,"alt":"제조지식 AI 비서 화면 — LOT 이력·유사 클레임 사례·MES 실시간 조회","src":"/screens/knowledge-ai.jpg","width":1600,"height":900},"url":"max.drvalue.co.kr / AI 비서","tone":"steel"}]}$seed$::jsonb, now(), 'seed')
