INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('business-smart-fac', 'ko-KR', $seed${"shell":{"kicker":"스마트 팩토리 사업","kickerSub":"M.AX","headLead":"제조 현장의 가치를 데이터로, ","headStrong":"디알밸류 스마트팩토리 솔루션","desc":"생산성은 높이고, 비용은 낮추는 지능형 공장 구축의 표준","ctaTitle":"디알밸류와 함께 제조업의 혁신을 시작하세요.","ctaDesc":"현장 진단부터 정부지원사업 연계까지 전문가가 직접 상담해 드립니다."},"lead":{"title":"단순한 자동화를 넘어 데이터로 스스로 판단하는 지능형 공장","desc":"디알밸류는 현장의 모든 설비와 공정을 디지털로 연결하여 실시간 최적화를 실현합니다. 단순히 시스템을 설치하는 것에 그치지 않고, 기업의 제조 원가 경쟁력을 실질적으로 높이는 현장 맞춤형 스마트팩토리 아키텍처를 설계합니다.","heroN":"3단계","heroLabel":"데이터 수집부터 지능형 자동 제어까지","items":[{"t":"AI 자동 견적 (Costing)","d":"도면을 AI 가 바로 분석해 제조 원가와 납기를 예측합니다."},{"t":"IoT 통합 모니터링","d":"설비 센서 데이터를 실시간으로 모아 가동 상태와 에너지 효율을 대시보드로 봅니다."},{"t":"MES/ERP 실시간 연계","d":"생산 계획부터 재고·출하까지 끊김 없이 이어 '보이는 관리' 를 만듭니다."}]},"features":[{"no":"1","kicker":"구축 전략 3단계","title":"현장 중심의 고도화된 **구축 전략 3단계**","points":[{"text":"**단계별 맞춤형 고도화** — 기초 단계의 데이터 수집부터 최종 단계인 지능형 자동 제어까지, 귀사의 예산과 환경에 맞춘 단계별 로드맵을 제공합니다."},{"text":"**현장 설비 호환성 극대화** — 노후 설비부터 최신 CNC까지, 이기종 간의 데이터 통신 표준화 기술로 완벽한 통합 네트워크를 구축합니다."},{"text":"**AI 기반 예지보전** — 설비의 진동과 전류 데이터를 분석하여 고장이 발생하기 전 사전에 유지보수 타이밍을 알려줌으로써 손실을 방지합니다."}],"chips":[{"text":"단계별 로드맵"},{"text":"이기종 설비 통합"},{"text":"AI 예지보전"}],"calloutLead":"","calloutResult":"","shots":[]}]}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('business-ai-sol', 'ko-KR', $seed${"shell":{"kicker":"AI 솔루션 개발","kickerSub":"AI솔루션","headLead":"기업의 혁신을 완성하는 ","headStrong":"맞춤형 AI 솔루션 파트너, 디알밸류","desc":"최신 LLM 기술부터 보안이 강조된 온프레미스 기반 로컬 AI까지, 기업 내부 데이터를 기반으로 답변하는 RAG 시스템을 구축합니다.","heroLink":"만들어 둔 것 보기","ctaTitle":"사내 자료로 답하는 AI, 디알밸류와 시작하는 게 가장 빠릅니다","ctaDesc":"만들어 둔 제품 다섯을 상용으로 돌리고 있습니다. 어떤 자료가 얼마나 있는지만 알려주세요."},"lead":{"title":"단순한 도입을 넘어 비즈니스에 최적화된 지능형 엔진","desc":"디알밸류는 최신 LLM 기술부터 보안이 강조된 온프레미스 기반 로컬 AI까지 기업 환경에 최적화된 맞춤형 솔루션을 제안합니다. 기업 내부 데이터를 기반으로 답변하는 RAG 시스템 구축을 통해 정확하고 신뢰할 수 있는 차세대 AI 서비스를 실현합니다.","heroN":"RAG","heroLabel":"사내 문서로 답한다 — 환각 없이","items":[{"t":"Global LLM 최적화","d":"GPT-4, Claude 등을 업무와 연동해 챗봇·요약·번역을 자동화합니다."},{"t":"보안 특화 로컬 LLM","d":"기업 내부 인프라에 모델을 두어 데이터가 밖으로 나가지 않습니다."},{"t":"RAG 기반 지식 서비스","d":"기업 문서를 실시간 검색해 할루시네이션 없는 답을 냅니다."}]},"heroShots":[{"image":{"id":null,"alt":"제조지식 AI 비서 화면 — LOT 이력·유사 클레임 사례·MES 실시간 조회","src":"/screens/knowledge-ai.jpg","width":1600,"height":900},"tag":"RAG · 사내 자료로 답합니다","url":"drvalue.co.kr / 제조지식 AI 비서"}],"road":{"kicker":"AI 개발 로드맵","title":"디알밸류가 지원하는 AI 개발 로드맵","items":[{"t":"기업 맞춤형 Fine-Tuning","d":"특정 산업군과 직무에 특화된 언어 모델로 고도화하여 업무 적합성을 극대화합니다."},{"t":"지능형 에이전트 개발","d":"단순 답변을 넘어 작업 수행, 일정 관리 등 복잡한 워크플로우를 직접 실행하는 AI 에이전트를 구축합니다."},{"t":"전사적 AI 통합 인프라","d":"기존 ERP, 그룹웨어 등 내부 시스템과 완벽하게 연동되는 AI 인터페이스를 설계합니다."}]},"autoformTabs":[{"image":{"id":null,"alt":"양식 등록 화면 — 올린 한글 양식 목록과 분석·연결 상태","src":"/screens/solution-form-automation-upload.jpg","width":1600,"height":1121},"tag":"양식 등록","url":"autoform / 양식 등록","t":"쓰던 한글 양식을 그대로 올립니다","d":"현업에서 오랫동안 써 온 HWP · HWPX 원본 양식을 그대로 등록","tone":"sand"},{"image":{"id":null,"alt":"매핑 화면 — 한글 원본과 DB 스키마를 나란히 놓고 칸을 맺는다","src":"/screens/solution-form-automation-mapping.jpg","width":1600,"height":799},"tag":"데이터 연결","url":"autoform / 매핑","t":"문서 칸과 업무 데이터를 맺어 둡니다","d":"문서 입력 영역과 DB 데이터 스키마 사이의 매핑 규칙을 설정","tone":"sand"},{"image":{"id":null,"alt":"문서 생성 화면 — 레코드를 골라 채운 문서","src":"/screens/solution-form-automation-generate.jpg","width":1600,"height":1024},"tag":"문서 생성","url":"autoform / 생성","t":"레코드를 고르면 문서가 나옵니다","d":"날짜 · 거래처 · 품목 · 생산 배치로 실시간 제조 데이터를 검색해 선택","tone":"sand"}],"cutonTabs":[{"image":{"id":null,"alt":"예상견적산출 체험 화면 — sample-bracket.dxf 위에 항목 둘을 드래그로 잡은 상태","src":"/screens/cuton-sim.jpg","width":1440,"height":1300},"tag":"예상견적산출","url":"cuton.co.kr / 체험 가이드","t":"도면을 올리면 항목이 잡힙니다","d":"영역을 드래그해 항목을 만들고 재질그룹별 예상가를 한 번에 받습니다(체험 가이드 화면).","tone":"steel"},{"image":{"id":null,"alt":"견적 결과 화면 — 분석값과 재질그룹별 가격, 최저 합계","src":"/screens/cuton-result.jpg","width":1290,"height":810},"tag":"견적 결과","url":"cuton.co.kr / 체험 가이드","t":"재질그룹별 예상가가 같은 화면에","d":"분석값과 재질그룹 가격표, 최저 합계가 도면 옆에 바로 뜹니다.","tone":"steel"},{"image":{"id":null,"alt":"견적 상세 화면 — 왼쪽 품목·금액, 가운데 품목 기본 정보, 오른쪽 DXF 도면 미리보기와 치수","src":"/screens/cuton-main.jpg","width":1600,"height":900},"tag":"견적 상세","url":"cuton.co.kr / 견적 상세","t":"견적 상세와 도면 미리보기","d":"CAD 도면(DXF) 자동 분석 엔진 탑재","tone":"steel"}],"cadonTabs":[{"image":{"id":null,"alt":"STEP 미리보기 — 3D 형상을 돌려 보며 전개 대상을 고른다","src":"/screens/cuton-autocad-01-3d-preview.jpg","width":1600,"height":1347},"tag":"STEP 미리보기","url":"AutoCAD / CADON","t":"STEP 을 열어 전개할 부품을 고릅니다","d":"3D STEP 파일의 형상을 미리 확인","tone":""},{"image":{"id":null,"alt":"전개 결과 — AutoCAD 안에 절단선·절곡선이 레이어로 작도된다","src":"/screens/cuton-autocad-02-unfold-result.jpg","width":1600,"height":993},"tag":"전개 결과","url":"AutoCAD / CADON","t":"전개 결과가 도면 위에 그려집니다","d":"3D STEP 또는 2D DXF 를 바탕으로 전개 수행 — AutoCAD 에서 직접 고른 객체도 가능","tone":""},{"image":{"id":null,"alt":"절곡 시뮬레이션 — 스텝별 3D 형상과 각도·반경·DFM 검토","src":"/screens/cuton-autocad-03-bend-simulation.jpg","width":1600,"height":1000},"tag":"절곡 시뮬레이션","url":"AutoCAD / CADON","t":"절곡 순서를 돌려 보고 3D 로 되접습니다","d":"AutoCAD 안 팝업으로 PASS / REVIEW 결과를 실시간 확인","tone":""}],"chatTabs":[{"image":{"id":null,"alt":"고객 상담 창의 대화 — MES 도입 문의 두 건, 상담 시작, 상담사의 LOT 추적 답","src":"/screens/growchat-customer.jpg","width":924,"height":676},"tag":"고객 쪽","url":"growchat / 홈페이지 상담 창","t":"고객은 상담 버블에서 바로 대화","d":"전담 상담