INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-autoform', 'ko-KR', $seed${"shell":{"kicker":"오토폼","kickerSub":"AI솔루션","headLead":"쓰던 한글 양식 그대로, ","headStrong":"데이터만 채웁니다","desc":"기존 문서 양식과 제조 데이터를 연결해 반복적으로 작성하는 문서 업무를 지원합니다. 사용 중인 한글 양식을 바탕으로 데이터 연동 환경을 만듭니다.","ctaTitle":"쓰던 한글 양식 그대로, 오토폼으로 문서를 뽑아 보세요","ctaDesc":"양식 파일 하나와 채울 데이터가 어디 있는지만 알려주시면 됩니다."},"lead":{"title":"쓰던 서식을 바꾸지 않습니다","desc":"일반 사무문서뿐만 아니라 제조 현장의 필수 정형 서식까지, 지금 쓰고 있는 원본 포맷 그대로 현장 데이터베이스와 이어 붙여 반복 작성을 자동으로 지원합니다.","heroN":"그대로","heroLabel":"쓰던 한글 양식을 바꾸지 않습니다","items":[{"t":"양식을 그대로 올립니다","d":"지금 쓰는 한글 서식 원본을 그대로 씁니다."},{"t":"칸과 데이터를 맺어 둡니다","d":"문서 칸을 업무 데이터베이스와 한 번 이어 둡니다."},{"t":"레코드를 고르면 문서가 나옵니다","d":"반복 작성이 자동으로 끝납니다."}]},"heroShots":[{"image":{"id":null,"alt":"오토폼 양식 등록 화면 — 데이터베이스 연결 상태와 분석된 양식 9개 목록","src":"/screens/solution-form-automation-upload.jpg","width":1600,"height":1121},"tag":"오토폼 · 양식 등록","url":"form automation / 양식"}],"demo":{"kicker":"세 단계","title":"양식 한 번, 연결 한 번, 그다음은 고르기만","desc":"양식을 올리고, 칸마다 어느 데이터가 들어갈지 한 번 정하고, 그다음부터는 레코드를 고르기만 합니다. 아래는 실제 화면을 순서대로 다시 보여 주는 것입니다."},"compareStatement":{"kicker":"","title":"복사해 채우는 문서가 아니라 골라서 나오는 문서","desc":"지난 문서를 복사해 값을 찾아 넣고 서식이 깨지지 않게 손보던 일을, 레코드 하나 고르는 것으로 끝냅니다."},"compare":{"before":{"title":"같은 문서를 매번 처음부터 씁니다","points":[{"text":"값을 찾아 복사해 넣는 손이 문서마다 든다"},{"text":"양식을 새로 만들면 부서마다 서식이 달라진다"},{"text":"표가 넘치면 서식이 깨진 채 나간다"}],"bubbles":[{"who":"me","t":"지난달 품질관리기록서 파일 어디 있어요? 그거 복사해서 쓰게"},{"who":"them","t":"제조번호랑 제조량은 MES 에서 다시 찾아서 붙여 넣어야 해요"},{"who":"me","t":"검사항목 표가 넘쳐서 두 쪽으로 밀렸는데 서식 깨졌어요…"}]},"after":{"title":"레코드 하나 고르면 서식 그대로 나옵니다","points":[{"text":"쓰던 hwp·hwpx 원본을 그대로 등록 — 「라벨·리스트를 자동 감지하고 매핑 초안을 만들어 드려요」"},{"text":"「제품명 ← name」처럼 칸과 데이터를 한 번 맺어 두면 다음부터는 고르기만"},{"text":"넘치면 「문서를 만들지 않고 알림」 또는 「행을 늘려서 전부 넣기」 — 깨진 채 나가지 않는다"}]},"shot":{"id":null,"alt":"오토폼 매핑 화면 — 한글 원본 위에 제품명·제조번호 같은 칸과 데이터 항목의 대응이 표시된다","src":"/screens/solution-form-automation-mapping.jpg","width":1600,"height":799}},"extra":{"kicker":"양식","title":"견적서도, 두 쪽짜리 기록서도, 빈 서식도 같은 방식으로","desc":"등록 화면의 목록에 있는 양식 셋입니다. 파일마다 쪽·표·스칼라·리스트 수를 읽어 두고, 같은 데이터베이스에서 채웁니다."}}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-cuton', 'ko-KR', $seed${"shell":{"kicker":"컷온","kickerSub":"AI솔루션","headLead":"도면 업로드 한 번으로 끝나는 ","headStrong":"AI 레이저 절삭 자동 견적, 컷온","desc":"도면(CAD) 데이터를 AI가 즉시 분석하여 최적의 절삭 비용을 산출하는 자동 견적 플랫폼입니다.","ctaTitle":"도면을 올리면 견적까지, 컷온으로 먼저 받아 보세요","ctaDesc":"cuton.co.kr 체험 가이드는 로그인 없이 바로 열립니다. 도입·연동 상담은 아래로."},"lead":{"title":"기다림 없는 견적 산출, 스마트한 제조의 시작","desc":"컷온(CutOn)은 도면(CAD) 데이터를 AI가 즉시 분석하여 최적의 절삭 비용을 산출하는 자동 견적 플랫폼입니다. 번거로운 유선 문의와 며칠씩 걸리는 견적 대기 시간을 초 단위로 단축하여 업무 효율을 혁신합니다.","heroN":"10초","heroLabel":"도면 올리고 견적 받기까지","items":[{"t":"초고속 자동 견적","d":"복잡한 형상의 도면도 AI 가 실시간으로 분석해 10초 이내에 견적을 냅니다."},{"t":"높은 신뢰도와 정확성","d":"수만 건의 가공 데이터로 재료비·가공비·마진율을 계산합니다."},{"t":"원스톱 주문 시스템","d":"견적 그대로 바로 발주하고, 공정 현황까지 실시간으로 봅니다."}]},"heroShots":[{"image":{"id":null,"alt":"견적 상세 화면 — 왼쪽 품목·금액, 가운데 품목 기본 정보, 오른쪽 DXF 도면 미리보기와 치수","src":"/screens/cuton-main.jpg","width":1600,"height":900},"tag":"컷온 · 자동 견적","url":"cuton.co.kr"}],"demo":{"kicker":"예상견적산출","title":"도면 한 장 올리면 재질그룹별 예상가까지","desc":"DXF 도면을 올리면 형상을 분석해 절단 길이·구멍·면적을 읽고, 재질그룹별 예상가를 같은 화면에서 냅니다. 아래는 컷온이 사이트에 열어 둔 체험 가이드를 그대로 따라간 것입니다 — 가이드의 예시 도면·값으로, 실제 화면과 같은 흐름입니다."},"compareStatement":{"kicker":"","title":"기다리는 시간이 아니라 고르는 시간","desc":"도면을 보내고 회신을 기다리던 일을, 올리고 고르는 일로 바꿉니다."},"compare":{"before":{"title":"도면 보내고 답을 기다리는 데 며칠이 갑니다","points":[{"text":"전화·메일로 도면을 보내고 답을 기다린다"},{"text":"재질·두께가 바뀌면 처음부터 다시 묻는다"},{"text":"업체마다 따로 물어봐야 금액이 비교된다"}],"bubbles":[{"who":"me","t":"브라켓 10개 레이저 절단 견적 부탁드립니다. 도면 첨부합니다."},{"who":"them","t":"담당자 확인 후 연락드리겠습니다."},{"who":"them","t":"재질이 뭐였죠? 두께는요? 후가공은 있나요?"}]},"after":{"title":"도면을 올리면 금액이 바로 나옵니다","points":[{"text":"DXF 파일을 업로드하면 AI가 형상을 자동 분석하여 재질, 두께, 수량에 따른 견적을 실시간으로 산출합니다"},{"text":"재질 · 두께 · 수량 입력으로 즉시 금액 반영"},{"text":"보관된 견적을 입찰로 등록하면, 국내 파트너 레이저 업체들이 직접 제안을 보내옵니다"}]},"shot":{"id":null,"alt":"컷온 예상견적산출 결과 화면 — 항목별 분석값과 재질그룹별 가격, 최저 합계가 한 화면에","src":"/screens/cuton-result.jpg","width":1290,"height":810}},"extra":{"kicker":"견적 · 보관 · 입찰","title":"견적에서 발주까지 한 흐름으로","desc":"도면을 올려 예상가를 받고, 보관함에 저장하고, 그대로 입찰마켓에 올려 업체 제안을 받습니다. 컷온 체험 가이드의 세 화면입니다."}}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-cadon', 'ko-KR', $seed${"shell":{"kicker":"CADON in AutoCAD","kickerSub":"AI솔루션","headLead":"AutoCAD 안에서 판금을 ","headStrong":"펴고 되짚습니다","desc":"3D STEP 또는 2D DXF 도면을 바탕으로 전개 결과를 확인하고, 절단선·절곡선 작도와 DFM 검토, 절곡 시뮬레이션까지 AutoCAD 작업 환경에서 끝냅니다.","ctaTitle":"도면은 밖으로 나가지 않습니다 — CADON 으로 AutoCAD 안에서 전개하세요","ctaDesc":"쓰시는 AutoCAD 버전과 판금 자재를 알려주시면 적용 방안을 검토해 드립니다."},"lead":{"title":"도면은 밖으로 나가지 않습니다","desc":"외부 서버에 올리지 않고 AutoCAD 환경 안에서만 처리합니다. 3D STEP 또는 2D DXF 를 바탕으로 전개하고, 절단선·절곡선 작도와 DFM 검토, 절곡 시뮬레이션과 3D 되접기까지 같은 작업 환경에서 끝냅니다.","heroN":"3D → 2D","heroLabel":"STEP 을 열어 전개까지 AutoCAD 안에서","items":[{"t":"STEP 을 열어 부품을 고릅니다","d":"전개할 부품을 그 자리에서 정합니다."},{"t":"전개 결과를 바로 받습니다","d":"절단선·절곡선 작도까지 같은 창에서 끝납니다."},{"t":"DFM 검토와 절곡 시뮬레이션","d":"만들 수 있는 형상인지 보고, 절곡 순서를 단계별로 돌려 봅니다."}]},"heroShots":[{"image":{"id":null,"alt":"CutON 전개 결과 — AutoCAD 도면 위에 절단선·절곡선이 작도되고, PASS 1 · A1100 t 2 · 절곡 6 · DFM 경고 4 패널이 뜬다","src":"/screens/cadon-02-unfold.jpg","width":1600,"height":993},"tag":"CADON · 전개 결과","url":"AutoCAD / CADON"}],"demo":{"kicker":"전개 한 번","title":"STEP 을 열어 전개하고, 돌려 보고, 되접기까지 AutoCAD 안에서","desc":"STEP 을 열고 「이 파일로 전개」를 누르면 전개도가 도면 위에 그려지고, 절곡 순서를 돌려 본 뒤 다시 3D 로 되접어 확인합니다. 아래는 부품 하나를 실제로 돌린 화면을 순서대로 다시 보여 주는 것입니다."},"compareStatement":{"kicker":"","title":"기다리는 시간이 아니라 검토하는 시간","desc":"외부 전개 서비스에 올리고 기다리던 일을, AutoCAD 명령 하나로 그 자리에서 끝냅니다."},"compare":{"before":{"title":"전개 한 번에 도면이 밖으로 나갑니다","points":[{"text":"STEP 을 외부 서비스에 올려야 전개가 된다"},{"text":"전개도가 와야 절단선·절곡선을 다시 그린다"},{"text":"만들 수 있는 형상인지는 받아 본 뒤에 안다"}],"bubbles":[{"who":"me","t":"unistrut 전개도 언제 오나요? 절곡 6개짜리인데"},{"who":"them","t":"외주 전개 서비스에 올려 뒀어요. 내일 오후요"},{"who":"me","t":"플랜지 짧은 데 있는 것 같은데, 그건 받아 봐야 아나요?"}]},"after":{"title":"AutoCAD 안에서 열고, 펴고, 되접습니다","points":[{"text":"STEP 을 열어 그 자리에서 전개 — 도면이 밖으로 나가지 않는다"},{"text":"절단선·절곡선이 레이어로 자동 작도 · A1100 t 2 · 절곡 6"},{"text":"「플랜지 길이 6.32mm 가 최소 성형 길이 8.00mm 미만」 — DFM 경고가 같이 뜬다"}]},"shot":{"id":null,"alt":"CutON 절곡 시뮬레이션 화면 — 스텝별 형상과 DFM 위반","src":"/screens/cuton-autocad-03-bend-simulation.jpg","width":1600,"height":880}},"extra":{"kicker":"검토","title":"만들 수 있는 형상인지 그 자리에서 봅니다","desc":"전개가 끝나면 PASS · REVIEW · 실패로 판정하고, 만들 수 없는 플랜지는 어느 스텝에서 얼마나 짧은지 짚어 줍니다. 아래는 같은 부품의 실제 패널입니다."}}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-chat', 'ko-KR', $seed${"shell":{"kicker":"채팅","kickerSub":"AI솔루션","headLead":"고객과 상담원을 ","headStrong":"곧바로 잇습니다","desc":"홈페이지 오른쪽 아래 버블을 누르면 문의가 열리고, 상담원은 한 화면에서 배정받아 답합니다. 디알밸류 홈페이지가 지금 쓰는 그 창입니다.","ctaTitle":"고객과 상담원을 곧바로 잇는 채팅, 지금 이 홈페이지에서 써 보세요","ctaDesc":"오른쪽 아래 상담 버블이 바로 그 창입니다. 도입 상담은 아래에서."},"lead":{"title":"두 가지 방식으로 받습니다","desc":"고객 문의의 긴급도와 성격에 따라 실시간 대화와 게시판 방식을 유연하게 제공합니다.","heroN":"2가지","heroLabel":"실시간 상담과 게시판형 문의","items":[{"t":"실시간 상담","d":"고객과 상담원이 실시간으로 메시지를 주고받으며 문의 사항을 빠르게 확인하고 응대하는 방식입니다."},{"t":"게시판형 문의","d":"고객이 문의 내용을 남기고, 상담원이 확인 후 답변을 작성하여 전달하는 게시판 형태의 응대 방식입니다."}]},"agentShot":{"id":null,"alt":"상담원 관리자센터 — 왼쪽 대기중·진행중 방 목록, 가운데 대화와 상담전송·내부전송, 오른쪽 현재 상담 정보","src":"/screens/growchat-agent.jpg","width":1600,"height":1000},"customerShot":{"id":null,"alt":"고객 상담 창의 대화 — PCB MES 도입 문의 두 건, 「상담이 시작되었습니다」, 상담사의 LOT 추적 답","src":"/screens/growchat-customer.jpg","width":924,"height":676},"compareStatement":{"kicker":"","title":"받는 곳이 하나면 놓치는 문의가 없습니다","desc":"전화 한 통, 메일 한 줄로 흩어지던 문의가 방 하나에 상태와 함께 모입니다."},"compare":{"before":{"title":"전화와 메일로 받으면 문의가 흩어집니다","points":[{"text":"전화·메일·게시판이 따로 놀아 같은 문의를 두 번 받는다"},{"text":"누가 응대 중인지, 답했는지 아무도 모른다"},{"text":"지난 문의 이력이 담당자 메일함에만 남는다"}],"bubbles":[{"who":"me","t":"어제 메일로 문의드렸는데 답이 없어서요"},{"who":"them","t":"담당자가 외근이라… 어느 메일이었죠? 다시 보내 주시겠어요?"},{"who":"me","t":"전화로 말씀드린 건데 파일도 같이 보내야 하나요?"}]},"after":{"title":"한 화면에서 받고, 배정하고, 답합니다","points":[{"text":"대기중 → 배정 → 진행중 → 완료, 상태가 방마다 보인다"},{"text":"대화 옆에 고객 정보와 이전 상담 이력이 같이 뜬다"},{"text":"상담원끼리는 고객에게 보이지 않는 「내부 대화」로 상의한다"}]},"shot":{"id":null,"alt":"상담원 관리자센터 — 왼쪽 대기중·진행중 방 목록, 가운데 대화와 상담전송·내부전송, 오른쪽 현재 상담 정보","src":"/screens/growchat-agent.jpg","width":1600,"height":1000}}}$seed$::jsonb, now(), 'seed')
