INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-hangeon', 'ko-KR', $seed${"shell":{"kicker":"한건 AI Chat","kickerSub":"AI솔루션","headLead":"건설 법령·기준을 ","headStrong":"근거와 함께 답합니다","desc":"LLM 과 RAG 를 함께 써서 KCS·KDS·표준품셈과 법령 조문을 근거로 답하는 건설 AI 입니다. 디알밸류가 만들어 상용으로 운영하고 있습니다.","ctaTitle":"건설 법령을 근거와 함께, 한건을 먼저 써 보세요","ctaDesc":"hankeon.com 에서 바로 쓸 수 있습니다. 우리 회사 자료로 같은 구조를 만들려면 도입 상담으로."},"lead":{"title":"자료를 근거로 답합니다","desc":"","heroN":"LLM + RAG","heroLabel":"KCS·KDS·표준품셈을 근거로 답하는 건설 AI","items":[{"t":"묻고 답하는 AI Chat","d":"건설 기준·법령을 근거로 대답합니다."},{"t":"상용 운영 중","d":"디알밸류가 만들어 상용으로 운영하고 있습니다."},{"t":"제조 현장에도 같은 방식","d":"사내 자료로 같은 구조를 만듭니다."}]},"heroShots":[{"image":{"id":null,"alt":"한건 Chat 화면 — 지하층 직통계단·특별피난계단 질문에 건축법 시행령 34조·35조, 피난·방화규칙 9조를 인용해 답한다","src":"/screens/hankeon-chat.jpg","width":1600,"height":1000},"tag":"Chat · 근거 기반 질의응답","url":"hankeon.com / chat"}],"demo":{"kicker":"Chat","title":"“지하 2층 직통계단, 특별피난계단으로 해야 합니까?” 조문을 짚어 답합니다","desc":"질문 한 줄을 넣으면 질문을 분류하고, 자료를 찾고, 어느 법령이 걸리는지 판정한 뒤 조문을 인용해 답합니다. 아래는 실제 응답을 순서대로 다시 보여 주는 것입니다."},"compareStatement":{"kicker":"","title":"찾는 시간이 아니라 판단에 쓰는 시간","desc":"법령·시행령·규칙 세 곳을 오가며 조문을 대조하던 일을, 질문 한 줄로 끝냅니다."},"compare":{"before":{"title":"조문을 찾아 대조하는 데 하루가 갑니다","points":[{"text":"법령·시행령·규칙이 세 곳에 흩어져 있다"},{"text":"조문 번호를 알아야 검색이 된다"},{"text":"찾아도 이 건물에 적용되는지는 다시 판단해야 한다"}],"bubbles":[{"who":"me","t":"지하 2층 직통계단, 특별피난계단으로 해야 하나요?"},{"who":"them","t":"시행령 35조 볼게요… 규칙 9조도 봐야 할 것 같은데"},{"who":"me","t":"거실 면적 기준은 34조였나요, 35조였나요?"}]},"after":{"title":"질문 한 줄에 조문과 판단이 같이 옵니다","points":[{"text":"「건축법 시행령」 34조·35조, 피난·방화규칙 9조를 근거로 인용"},{"text":"「지하층 거실 바닥면적 200㎡ 이상이면 2개소」 — 판단까지 확정"},{"text":"모르면 모른다고 답한다 — 「제공된 자료로는 확정할 수 없습니다」"}]},"shot":{"id":null,"alt":"한건 Chat 답변 화면 — 조문 인용과 판단 요약","src":"/screens/hankeon-chat.jpg","width":1600,"height":1000}},"extra":{"kicker":"Biz","title":"공고 100건 중 우리가 낼 수 있는 건 2건 — 이유까지 붙여서","desc":"내 정보·면허를 한 번 적어 두면 나라장터·지자체 공고를 면허와 지역 기준으로 가려 줍니다. 아래는 「부산 소재 · 건축공사업 + 실내건축공사업」 프로필로 2026-09-22 실제 조회한 결과입니다."}}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-growtok', 'ko-KR', $seed${"shell":{"kicker":"GrowTalk","kickerSub":"AI솔루션","headLead":"현장의 목소리를 데이터로, ","headStrong":"지능형 협업 플랫폼 GrowTalk","desc":"제조·공공기관·쇼핑몰 운영사 등 현장의 실시간 상황을 데이터화하여 신속한 의사결정을 돕는 스마트 협업 플랫폼입니다.","ctaTitle":"GrowTalk으로 스마트한 현장을 만들어보세요","ctaDesc":"현장과 사무실이 같은 화면에서 이야기합니다."},"lead":{"title":"현장·매니저·관리자를 잇는 가장 똑똑한 방법","desc":"GrowTalk은 제조·공공기관·쇼핑몰 운영사 등 현장의 실시간 상황을 데이터화하여 신속한 의사결정을 돕는 스마트 협업 플랫폼입니다. 단순한 메시징을 넘어, 현장의 이슈를 감지하고 분석하여 생산 효율을 극대화합니다.","heroN":"현장 → 관리자","heroLabel":"한 대화방에서 이슈가 데이터가 됩니다","items":[{"t":"실시간 이슈 공유","d":"설비 이상·품질 문제를 그 자리에서 공유해 대응 시간을 줄입니다."},{"t":"데이터 기반 분석","d":"쌓인 대화와 이슈 리포트를 AI 가 분석해 반복 문제의 원인을 찾습니다."},{"t":"모바일 최적화","d":"PC 와 모바일이 같이 움직여 현장 엔지니어부터 경영진까지 어디서든 봅니다."}]},"features":[{"no":"1","kicker":"현장의 디지털 혁신","title":"GrowTalk이 선사하는 **현장의 디지털 혁신**","points":[{"text":"**AI 비서** 기반의 업무 자동화 및 스케줄링"},{"text":"**음성 인식**을 통한 실시간 작업 일지 기록"},{"text":"공정 데이터와 연동된 **지능형 알림** 시스템"},{"text":"과거 이슈 데이터베이스 기반 **해결 가이드** 제공"}],"chips":[{"text":"AI 비서"},{"text":"음성 작업일지"},{"text":"지능형 알림"},{"text":"해결 가이드"}],"calloutLead":"","calloutResult":"","shots":[]}]}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;

INSERT INTO page_contents (key, languages_code, content, updated_on, updated_by)
VALUES ('service-growxd', 'ko-KR', $seed${"shell":{"kicker":"GrowXD","kickerSub":"AI솔루션","headLead":"AI가 스스로 최적화하는 ","headStrong":"지능형 생산 관리 시스템, GrowXD","desc":"단순한 실적 수집(MES)을 넘어 AI 기반의 분석과 예측 기능을 결합한 차세대 제조실행시스템입니다.","ctaTitle":"GrowXD와 함께 자율 제조의 시대를 시작하세요","ctaDesc":"현장 데이터부터 전사 지표까지 한 흐름으로 잇습니다."},"lead":{"title":"기존 MES를 넘어선 데이터 기반의 자율 제조","desc":"GrowXD는 단순한 실적 수집(MES)을 넘어 AI 기반의 분석과 예측 기능을 결합한 차세대 제조실행시스템입니다. 공정의 모든 데이터를 실시간으로 통찰하고, 스스로 최적의 생산 경로를 제안하여 스마트 팩토리의 완성도를 높입니다.","heroN":"예측","heroLabel":"불량과 고장을 일어나기 전에 봅니다","items":[{"t":"지능형 공정 제어","d":"설비 상태와 생산 계획을 실시간 분석해 병목을 미리 막습니다."},{"t":"품질 예측 솔루션","d":"센서 데이터로 불량 가능성을 먼저 잡아 공정 손실을 줄입니다."},{"t":"설비 예지 보전","d":"진동·소음·전류로 고장 시점을 예측하고 점검 주기를 제안합니다."}]},"features":[{"no":"1","kicker":"핵심 아키텍처","title":"GrowXD의 **핵심 아키텍처**","points":[{"text":"**Edge-to-Cloud 데이터 통합** — 현장 장비(Edge)부터 전사적 관리(Cloud)까지 끊김 없는 데이터 수집 체계를 구축합니다."},{"text":"**실시간 대시보드 시각화** — 복잡한 제조 공정을 한눈에 파악할 수 있는 사용자 맞춤형 디지털 트윈 대시보드를 제공합니다."},{"text":"**유연한 확장성** — 표준 API 아키텍처를 기반으로 ERP, SCM 등 기존 시스템과 완벽하게 연동됩니다."}],"chips":[{"text":"Edge-to-Cloud"},{"text":"실시간 대시보드"},{"text":"표준 API"}],"calloutLead":"","calloutResult":"","shots":[{"image":{"id":null,"alt":"전사 현황 화면 — 당일 수주량·투입량·불량 수와 사양·지시서·출고 대기","src":"/screens/pcb-dash.jpg","width":1600,"height":1000}}]}]}$seed$::jsonb, now(), 'seed')
ON CONFLICT (key, languages_code) DO NOTHING;
